parameters.jsonBody:
={
  "model": "sonar",
  "messages": [{"role": "user", "content": "What GitHub repositories are trending today in {{ $json.topics }}? Which repos gained the most stars this week? Include repo names, star counts, what they do, and why they are gaining traction."}],
  "search_recency_filter": "week"
}

parameters.jsCode:
const items = $input.item.json.items || [];
const top = items.slice(0,10).map(r => ({
  name: r.full_name,
  description: r.description,
  stars: r.stargazers_count,
  language: r.language,
  url: r.html_url,
  topics: r.topics,
  created: r.created_at?.split('T')[0],
  forks: r.forks_count
}));
return [{ json: { repos: top } }];

